# characters; the harness shows about 5000\nTEST_LINES = 6\nDEF_LINES = 3\nCOMMITS = 5\nHUNK_TRIES = 5  # changed lines come from the newest of the first HUNK_TRIES commits that has some\nHUNK_LINES = 18\nWINDOW = 3  # context lines around each changed line that has the name\nLOG_LINES = 3\nLINE_MAX = 150\nTEST_PATHS = [":(glob)**/test/**/*.py", ":(glob)**/tests/**/*.py", ":(glob)**/testing/**/*.py", ":(glob)**/test_*.py", ":(glob)**/*_test.py"]\nPY = [":(glob)**/*.py"]  # history and changed lines: Python files only (docs translations drown everything else)\nLOG_PATHS = [":(glob)**/CHANGELOG*", ":(glob)**/CHANGES*", ":(glob)**/HISTORY*", ":(glob)**/NEWS*", ":(glob)**/release-notes*",\n             ":(glob)**/changelog*"]\n\n\ndef workspace():\n    """The repository root. The skill wrapper chdirs into a temp dir, so look for the directory it started in."""\n    for frame in inspect.stack():\n        cwd = frame.frame.f_locals.get("_orig_cwd")\n        if isinstance(cwd, str) and os.path.isdir(os.path.join(cwd, ".git")):\n            return cwd\n    for cand in (os.environ.get("PYTHONPATH", "").split(os.pathsep)[0], "/workspace", os.getcwd()):\n        if cand and os.path.isdir(os.path.join(cand, ".git")):\n            return cand\n    sys.exit("repository not found")\n\n\ndef git(ws, args, start):\n    """stdout lines of one git call, [] on error, timeout or when the deadline has passed."""\n    left = DEADLINE - (time.time() - start)\n    if left < 1:\n        return None\n    try:\n        r = subprocess.run(["git", "-c", "core.quotepath=off"] + args, cwd=ws, capture_output=True, text=True,\n                           timeout=min(CALL_TIMEOUT, left), stdin=subprocess.DEVNULL, errors="replace")\n    except subprocess.TimeoutExpired:\n        return []\n    return r.stdout.splitlines() if r.returncode in (0, 1) else []\n\n\ndef short(line):\n    line = line.rstrip()\n    return line if len(line) <= LINE_MAX else line[:LINE_MAX] + " ..."\n\n\ndef names_from_args():\n    raw = [a for a in sys.argv[1:] if a != "--"]\n    names = []\n    for a in raw:\n        for part in re.split(r"[\\n,]", a):\n            n = part.strip().strip("`\'\\"").strip()\n            if len(n) >= 3 and n not in names:\n                names.append(n)\n    return names[:MAX_NAMES]\n\n\ndef newest_hunks(ws, commit, name, start):\n    """Changed lines that contain NAME in COMMIT (Python source, not tests), with WINDOW lines around each, at most\n    HUNK_LINES. Files the commit created or deleted are skipped: a whole new file says nothing about the change."""\n    lines = git(ws, ["show", "--format=", "-U3", "--no-color", commit, "--"] + PY\n                + [":(exclude,glob)" + p[len(":(glob)"):] for p in TEST_PATHS], start)\n    if not lines:\n        return []\n    out, cur_file, hunk, skip = [], None, [], False\n\n    def flush():\n        if skip or not hunk:\n            return\n        hits = [i for i, h in enumerate(hunk) if h[:1] in "+-" and name in h]\n        keep = sorted({j for i in hits for j in range(max(0, i - WINDOW), min(len(hunk), i + WINDOW + 1))})\n        if keep:\n            out.append(f"  {cur_file}:")\n            prev = None\n            for j in keep:\n                if prev is not None and j != prev + 1:\n                    out.append("    ...")\n                out.append("    " + short(hunk[j]))\n                prev = j\n\n    for ln in lines:\n        if ln.startswith("diff --git"):\n            flush()\n            hunk, skip, cur_file = [], False, None\n        elif ln.startswith(("new file", "deleted file")):\n            skip = True\n        elif ln.startswith("+++ "):\n            cur_file = ln[6:] if ln.startswith("+++ b/") else ln[4:]\n        elif ln.startswith(("index ", "--- ", "similarity", "rename ")):\n            continue\n        elif ln.startswith("@@"):\n            flush()\n            hunk = []\n        else:\n            hunk.append(ln)\n    flush()\n    return out[:HUNK_LINES]\n\n\n_RANGE = []\n\n\ndef recent(ws, start):\n    """r76: git log -S only over the last 500 commits (the whole history is slow on large repositories)."""\n    if not _RANGE:\n        revs = git(ws, ["rev-list", "--max-count=500", "HEAD"], start) or []\n        _RANGE.append([revs[-1] + "..HEAD"] if len(revs) == 500 else [])\n    return _RANGE[0]\n\n\ndef section(ws, name, start):\n    out = [f"== {name}"]\n    tests = git(ws, ["grep", "-n", "-I", "-F", "-e", name, "--"] + TEST_PATHS, start)\n    if tests is None:\n        return out + ["  (skipped: time)"]\n    out.append(f"tests mentioning it: {len(tests)} lines" + ("" if tests else " (none)"))\n    out.extend("  " + short(t) for t in tests[:TEST_LINES])\n    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):\n        defs = git(ws, ["grep", "-n", "-I", "-E", "-e", rf"^[[:space:]]*(async def|def|class) {name}([^A-Za-z0-9_]|$)", "--", "*.py"], start) or []\n        if defs:\n            out.append("defined at:")\n            out.extend("  " + short(d) for d in defs[:DEF_LINES])\n    log = git(ws, ["log", "-S", name, "--no-merges", "--format=%h %ad %s", "--date=short", f"-n{COMMITS}"] + recent(ws, start) + ["--"] + PY, start)\n    if log is None:\n        return out + ["  (history skipped: time)"]\n    if log:\n        out.append("commits that added or removed it (newest first):")\n        out.extend("  " + short(c) for c in log)\n        for c in log[:HUNK_TRIES]:\n            hunks = newest_hunks(ws, c.split()[0], name, start)\n            if hunks:\n                out.append(f"what {c.split()[0]} changed around it:")\n                out.extend(hunks)\n                break\n    else:\n        out.append("commits that added or removed it: none found")\n    notes = git(ws, ["grep", "-n", "-I", "-i", "-F", "-e", name, "--"] + LOG_PATHS, start) or []\n    if notes:\n        out.append("changelog:")\n        out.extend("  " + short(n) for n in notes[:LOG_LINES])\n    return out\n\n\ndef main():\n    start = time.time()\n    names = names_from_args()\n    if not names:\n        print("NO NAMES: pass 2 to 5 exact names from the issue as positional_args, for example "\n              "[\\"function_name\\", \\"ClassName\\", \\"option_name\\"].")\n        return\n    ws = workspace()\n    done = os.path.join(ws, DONE_FILE)\n    if ONCE and os.path.exists(done):  # also after the harness re-runs the stage with no history: show the result again\n        print("ALREADY DONE: the search already ran and a second call is refused. Its result was:\\n"\n              + open(done, errors="replace").read() + "\\n" + REPLY)\n        return\n    parts = [f"REPOSITORY EVIDENCE for {\', \'.join(names)} (read-only searches; the issue stays the specification)"]\n    for n in names:\n        parts.extend(section(ws, n, start))\n    text = "\\n".join(parts)\n    if len(text) > OUT_MAX:\n        text = text[:OUT_MAX] + "\\n[cut]"\n    if ONCE:\n        os.makedirs(os.path.dirname(done), exist_ok=True)\n        open(done, "w").write(text)\n        text += "\\nThis was the only search: a second call is refused. " + REPLY\n    print(text + f"\\n[done in {time.time() - start:.0f} s]")\n\n\nif __name__ == "__main__":\n    main()\n'}, 'evidcfs': {'agent.yaml': '# evidcfs (r81): evidc with the few-shot prompt fixes (examples of correct call forms, heredoc checks, no budget numbers) (scripts/make_fewshot_arms.py)\nname: swe_agent\nagent_class: SequentialAgent\nsub_agents:\n  - config_path: evidence.yaml\n  - config_path: fixer.yaml\n', 'configs/evidence_sampling.yaml': '# r76 cheap evidence stage: thinking off; a mechanical job (pick names, call the script once, copy lines).\n# In the installed harness (adk_submission 0.2.13, resolvers/generation.py) any thinking_budget > 0 turns thinking ON and a\n# missing budget is filled with 4096, so include_thoughts: false alone does not switch it off; thinking_budget: 0 does\n# (schema ge=0, limits 0-32768; the request then carries enable_thinking false and no thinking_token_budget).\ntemperature: 0.2\ntop_p: 0.95\nmax_output_tokens: 1024\nthinking_config:\n  thinking_budget: 0\n  include_thoughts: false\n', 'configs/sampling.yaml': 'temperature: 0.2\ntop_p: 0.95\nmax_output_tokens: 8192\nthinking_config:\n  thinking_budget: 4096\n  include_thoughts: true\n', 'eval_config.yaml': 'evaluation:\n  timeout_seconds: 240\n  max_tool_calls: 29\n  max_time_minutes: 8\n  max_turns: 80\n', 'evidence.yaml': 'name: evidence\nmodel: gemma-4-31b-it-qat-w4a16-ct\ndescription: Runs one repository search for names in the issue and copies the lines that matter.\ninstruction: !include prompts/evidence.md\ninclude_contents: none  # fresh: the issue is in its system prompt (the harness re-runs the root agent after a nudge)\ntools:\n  - get_status\nskills:\n  - skills/evidence\noutput_key: evidence\ngenerate_content_config: !include configs/evidence_sampling.yaml\n', 'fixer.yaml': "name: fixer\nmodel: gemma-4-31b-it-qat-w4a16-ct\ninstruction: !include prompts/fixer.md\ntools:  # combo1's tool list\n  - run_command\n  - read_file\n  - edit_file\n  - write_file\n  - get_status\n  - submit_patch\ngenerate_content_config: !include configs/sampling.yaml\n", 'prompts/evidence.md': "Your only job is one search of the repository for the agent who fixes the issue after you. Your reply is copied into that agent's instructions and stays in front of it for the whole task, so it must hold real lines from the repository, not your opinions. You will not read code and you will not work on the fix.\n\nChoose two to four exact names from the issue below that the fix most likely touches: functions, methods, classes, options or parameters, written exactly as they appear in the issue or as they would appear in the code. Prefer the most specific names, such as convert_underscores, over common words, such as Header.\n\nCall run_skill_script with skill_name evidence, file_path scripts/evidence.py and positional_args holding those names, one name per item. That is your only call.\n\nThen reply with the lines of its result that best show where the fix belongs and how this code is meant to behave: where the names are defined, tests that use them, and the lines an earlier commit changed around them. Copy each line exactly as it was printed, with its file:line or commit, at most 10 lines and nothing else. If nothing in the result bears on the issue, reply with the single line NOTHING RELEVANT.\n\n# THE ISSUE (verbatim)\n{problem_description}", 'prompts/fixer.md': 'You are an autonomous software engineer. Your job: make the smallest correct change to the SOURCE code in /workspace so that the hidden tests for the issue below pass. The hidden tests were written from the issue text, so the exact names, messages, types and behaviours in the issue are the specification.\n\n# HARD LIMITS\n- Your tool calls and your time are limited. When either runs out, the working tree is graded as it is. An edit that exists counts, even if you never call `submit_patch`. An unedited tree always scores zero.\n- Never create, modify or delete test files (`test_*.py`, `*_test.py`, anything under `tests/`, `pytest.ini`, `conftest.py`). This is an automatic failure.\n- Scratch files go in /tmp only, and only through run_command (for example `cat > /tmp/check.py <<\'EOF\'`). write_file only writes inside /workspace, and any file left under /workspace becomes part of the graded patch.\n- Never run a full test suite (bare `pytest`, `pytest .`, `unittest discover`). Always name one test file, and add `-k` when you can.\n- Never look outside /workspace. All dependencies are already installed.\n\n# ORDER OF WORK\n- Locate and read, then edit as soon as you know where the wrong behaviour is produced. If you are unsure, make your best-guess edit in the most likely place. A wrong edit can still be corrected. Pure reading cannot score.\n- Then verify and correct. Once a source file is edited, do not start new exploration: check, fix, submit.\n- Always finish with `git status --short && git diff` followed by `submit_patch`.\n\n# EXAMPLES OF CORRECT CALLS (another repository; your names will differ)\nPrint the exact lines first, then copy them into the edit:\n- run_command: sed -n \'118,124p\' src/pkg/values.py\n  which prints:\n      def parse_value(raw, strict=False):\n          if raw is None:\n              return None\n          return raw.strip()\n- edit_file with filepath src/pkg/values.py, old_string copied character for character from that output (same indentation, no line numbers):\n          if raw is None:\n              return None\n  and new_string:\n          if raw is None or raw == "":\n              return None\nCheck a behaviour with a quoted heredoc, never with python -c and quotes inside quotes:\n- run_command:\n  python3 - <<\'EOF\'\n  from pkg.values import parse_value\n  print(repr(parse_value("")))\n  EOF\nA scratch file goes to /tmp through the shell. It is never written with write_file, and a tool name is never typed into the shell:\n- run_command:\n  cat > /tmp/check_values.py <<\'EOF\'\n  from pkg.values import parse_value\n  assert parse_value("") is None\n  print("ok")\n  EOF\n  python3 /tmp/check_values.py\nTo read a region with read_file, give start_line before end_line, for example start_line 118 and end_line 160.\n\n# PROCEDURE\n\n## 1. Extract the specification (no tool call)\nFrom the issue, list for yourself: the exact file, function, class or CLI name; the exact error message and exception type; the expected return value or output; the inputs that trigger the bug; every edge case mentioned (None, empty, negative, unicode, duplicates, defaults). Treat every concrete string and name in the issue as a literal that must appear exactly in your code.\n\n## 2. Locate\n- Use exact paths from the issue directly. When searches are necessary, combine independent searches for the issue\'s exact symbols, their callers and relevant test paths into one run_command. Use git grep with fixed-string patterns for literal identifiers and git ls-files for tracked file paths; each result should show its file path and line number where applicable.\n- Batch only searches whose inputs are already known. If the next search depends on the first result, inspect that result before searching again. Limit each search to about 20 matching lines and keep total output short; never dump whole files or the repository tree.\n- Once the target is located, read the relevant implementation plus one relevant caller or test case. When both paths and line ranges are known, read these small regions in one run_command using sed with explicit line ranges, or use read_file for a single region. Aim for about 40 lines per region and at most three regions per command. Include enough surrounding code to understand signatures, defaults and error handling.\n- For a bug: find where the wrong behaviour is produced and use the caller or test to understand the contract before editing.\n- For a feature: find the closest existing sibling (a similar function, option, class, or doc example) and copy its pattern, including registration points such as __all__, option lists, dispatch tables and imports.\n- Reuse paths and test names already discovered. Do not spend another tool call repeating a search that already answered the question.\n- If the issue includes a code snippet that reproduces the problem, you may run it once through a quoted heredoc as in the examples (python3 - <<\'EOF\' ... EOF) to see the real error. Never create a file under /workspace for it.\n\n## 3. Edit\n- Use edit_file for changes to existing code. Copy old_string character for character from lines you printed, as in the examples, including whitespace, and choose a short unique match. Use write_file only for a genuinely new source file that the issue requires.\n- If a tool result says "mandatory input parameters are not present", your edit_file or write_file call was cut apart: a text ended with a backtick or a stray quote and swallowed the next argument. Do not send the same call again. End every text right after its last character, never with a backtick. If it fails a second time, use the heredoc script described next.\n- If edit_file reports no match or multiple matches, print the exact source region and retry with a smaller unique snippet copied from it. Never repeat an identical failed edit. After two matching failures, use one inline Python script through run_command with a quoted heredoc; assert that the old text occurs exactly once before replacing it and writing the file. Preserve unrelated content and do not rewrite the file from memory.\n- Fix the cause, not the symptom. Do not special-case the example from the issue.\n- Change only what the issue requires. Keep existing signatures, defaults, and backward compatibility unless the issue says otherwise. Match the style, naming and error-handling idioms of the surrounding code.\n- If the same behaviour has parallel implementations (sync and async variants, Client and AsyncClient, several backends or transports, typing overloads, re-exports in `__init__.py` or `__all__`), apply the change to every one of them. Hidden tests often exercise more than one.\n- Use the exact exception class and exact message text from the issue. If the issue only describes the error, reuse the wording style of neighbouring error messages.\n- Handle every edge case you listed in step 1.\n- For documentation-code tasks (for example FastAPI), edit the executable code under `docs_src/`.\n\n## 4. Verify (briefly)\n- Find the test file with `find tests -name "*keyword*.py"`, then run `timeout 150 python -m pytest tests/path/test_x.py -x -q -k keyword`. Use `python3 -m unittest tests.test_x` for unittest projects.\n- Failures that come from missing fixtures, missing data, or import errors unrelated to your change are pre-existing. Ignore them. Never repair tests or the environment.\n- If a test related to your change fails, read the traceback, fix the source once, and rerun once. If no test can run, do one quoted-heredoc check as in the examples, or `python -m py_compile` on the edited file.\n\n## 5. Final check and submit\n- Run `git status --short && git diff` in one call. `git diff` alone hides untracked files, but `submit_patch` includes them. If you see an untracked scratch file or a changed test file, remove it or restore it with `git checkout --` before submitting. Confirm that: only source files changed; every name, message and type from step 1 appears exactly; nothing unrelated was touched; there are no leftover debug prints or stray files.\n- Call `submit_patch`. Confirm `patch_size > 0` and `files_changed > 0`. If either is 0, you have not edited anything. Edit now and submit again.\n- End with a single-sentence summary of the fix.\n\n# DECISION RULES\n- Ambiguous issue: choose the most literal reading of the issue text and act on it. Do not ask questions and do not stall.\n- Several possible locations: pick the one where the wrong behaviour is produced, not where it is merely observed.\n- Search returned nothing: try one different specific string, then edit your best candidate anyway.\n- Stuck after a failed fix: make a different, smaller change. Do not repeat the same edit.\n- Never conclude that nothing needs to change. Every task requires a non-empty source patch.\n\n# REPOSITORY EVIDENCE (found before you started; it stays here for the whole task)\nLines copied from a search of this repository for names in the issue: where they are defined, tests that use them, and lines that earlier commits changed around them. Use them to find and understand the code; the issue stays the specification.\n{evidence?}\n', 'skills/evidence/SKILL.md': "---\nname: evidence\ndescription: Searches the repository's tests, definitions, git history and changelog for a few exact names from the issue. Call run_skill_script with skill_name evidence, file_path scripts/evidence.py and positional_args holding the names.\n---\n\nCall run_skill_script with skill_name evidence, file_path scripts/evidence.py and positional_args holding two to four exact\nnames from the issue, one name per item. It prints what the repository says about each name and takes a few seconds.\n", 'skills/evidence/scripts/evidence.py': '"""Repository evidence for a few exact names from the issue, in one call (arm evid1, scripts/make_mine_arms.py).\n\nRun once per task by the evidence agent through run_skill_script (skill "evidence"), names as positional_args:\n\n    run_skill_script skill_name=evidence file_path=scripts/evidence.py positional_args=["convert_underscores", "Header"]\n\nWhy: r60\'s scouts found good evidence (the right test files, the earlier commits on the buggy lines) but explored for\n2-4 minutes. This script does the same fixed searches in seconds, read-only, inside the repository:\n  - tests that mention the name (git grep in test files),\n  - where the name is defined (def / class lines),\n  - the most recent commits that added or removed the name (git log -S) and the changed lines around it in the newest one,\n  - changelog lines that mention it.\nEvery git call has its own timeout and the whole script stops adding sections after DEADLINE seconds.\n"""\nimport inspect\nimport os\nimport re\nimport subprocess\nimport sys\nimport time\n\nONCE = True  # evid2 (r64): True -> a second call is refused (r63: told to make one call, the agent made 2-17)\nDONE_FILE = os.path.join(".git", "agent", "evidence_done")  # holds the first result, shown again on a refused call\nREPLY = \'Now reply with at most 10 lines of this result, copied exactly, and stop.\'  # evid3 (r65) swaps this: the stage\'s reply becomes its output\nDEADLINE = 8  # r76: seconds for all sections (evid3: 40; large private repos made it the stage\'s main cost)\nCALL_TIMEOUT = 4  # seconds per git call (evid3: 12)\nMAX_NAMES = 5\nOUT_MAX = 4800  # characters; the harness shows about 5000\nTEST_LINES = 6\nDEF_LINES = 3\nCOMMITS = 5\nHUNK_TRIES = 5  # changed lines come from the newest of the first HUNK_TRIES commits that has some\nHUNK_LINES = 18\nWINDOW = 3  # context lines around each changed line that has the name\nLOG_LINES = 3\nLINE_MAX = 150\nTEST_PATHS = [":(glob)**/test/**/*.py", ":(glob)**/tests/**/*.py", ":(glob)**/testing/**/*.py", ":(glob)**/test_*.py", ":(glob)**/*_test.py"]\nPY = [":(glob)**/*.py"]  # history and changed lines: Python files only (docs translations drown everything else)\nLOG_PATHS = [":(glob)**/CHANGELOG*", ":(glob)**/CHANGES*", ":(glob)**/HISTORY*", ":(glob)**/NEWS*", ":(glob)**/release-notes*",\n             ":(glob)**/changelog*"]\n\n\ndef workspace():\n    """The repository root. The skill wrapper chdirs into a temp dir, so look for the directory it started in."""\n    for frame in inspect.stack():\n        cwd = frame.frame.f_locals.get("_orig_cwd")\n        if isinstance(cwd, str) and os.path.isdir(os.path.join(cwd, ".git")):\n            return cwd\n    for cand in (os.environ.get("PYTHONPATH", "").split(os.pathsep)[0], "/workspace", os.getcwd()):\n        if cand and os.path.isdir(os.path.join(cand, ".git")):\n            return cand\n    sys.exit("repository not found")\n\n\ndef git(ws, args, start):\n    """stdout lines of one git call, [] on error, timeout or when the deadline has passed."""\n    left = DEADLINE - (time.time() - start)\n    if left < 1:\n        return None\n    try:\n        r = subprocess.run(["git", "-c", "core.quotepath=off"] + args, cwd=ws, capture_output=True, text=True,\n                           timeout=min(CALL_TIMEOUT, left), stdin=subprocess.DEVNULL, errors="replace")\n    except subprocess.TimeoutExpired:\n        return []\n    return r.stdout.splitlines() if r.returncode in (0, 1) else []\n\n\ndef short(line):\n    line = line.rstrip()\n    return line if len(line) <= LINE_MAX else line[:LINE_MAX] + " ..."\n\n\ndef names_from_args():\n    raw = [a for a in sys.argv[1:] if a != "--"]\n    names = []\n    for a in raw:\n        for part in re.split(r"[\\n,]", a):\n            n = part.strip().strip("`\'\\"").strip()\n            if len(n) >= 3 and n not in names:\n                names.append(n)\n    return names[:MAX_NAMES]\n\n\ndef newest_hunks(ws, commit, name, start):\n    """Changed lines that contain NAME in COMMIT (Python source, not tests), with WINDOW lines around each, at most\n    HUNK_LINES. Files the commit created or deleted are skipped: a whole new file says nothing about the change."""\n    lines = git(ws, ["show", "--format=", "-U3", "--no-color", commit, "--"] + PY\n                + [":(exclude,glob)" + p[len(":(glob)"):] for p in TEST_PATHS], start)\n    if not lines:\n        return []\n    out, cur_file, hunk, skip = [], None, [], False\n\n    def flush():\n        if skip or not hunk:\n            return\n        hits = [i for i, h in enumerate(hunk) if h[:1] in "+-" and name in h]\n        keep = sorted({j for i in hits for j in range(max(0, i - WINDOW), min(len(hunk), i + WINDOW + 1))})\n        if keep:\n            out.append(f"  {cur_file}:")\n            prev = None\n            for j in keep:\n                if prev is not None and j != prev + 1:\n                    out.append("    ...")\n                out.append("    " + short(hunk[j]))\n                prev = j\n\n    for ln in lines:\n        if ln.startswith("diff --git"):\n            flush()\n            hunk, skip, cur_file = [], False, None\n        elif ln.startswith(("new file", "deleted file")):\n            skip = True\n        elif ln.startswith("+++ "):\n            cur_file = ln[6:] if ln.startswith("+++ b/") else ln[4:]\n        elif ln.startswith(("index ", "--- ", "similarity", "rename ")):\n            continue\n        elif ln.startswith("@@"):\n            flush()\n            hunk = []\n        else:\n            hunk.append(ln)\n    flush()\n    return out[:HUNK_LINES]\n\n\n_RANGE = []\n\n\ndef recent(ws, start):\n    """r76: git log -S only over the last 500 commits (the whole history is slow on large repositories)."""\n    if not _RANGE:\n        revs = git(ws, ["rev-list", "--max-count=500", "HEAD"], start) or []\n        _RANGE.append([revs[-1] + "..HEAD"] if len(revs) == 500 else [])\n    return _RANGE[0]\n\n\ndef section(ws, name, start):\n    out = [f"== {name}"]\n    tests = git(ws, ["grep", "-n", "-I", "-F", "-e", name, "--"] + TEST_PATHS, start)\n    if tests is None:\n        return out + ["  (skipped: time)"]\n    out.append(f"tests mentioning it: {len(tests)} lines" + ("" if tests else " (none)"))\n    out.extend("  " + short(t) for t in tests[:TEST_LINES])\n    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):\n        defs = git(ws, ["grep", "-n", "-I", "-E", "-e", rf"^[[:space:]]*(async def|def|class) {name}([^A-Za-z0-9_]|$)", "--", "*.py"], start) or []\n        if defs:\n            out.append("defined at:")\n            out.extend("  " + short(d) for d in defs[:DEF_LINES])\n    log = git(ws, ["log", "-S", name, "--no-merges", "--format=%h %ad %s", "--date=short", f"-n{COMMITS}"] + recent(ws, start) + ["--"] + PY, start)\n    if log is None:\n        return out + ["  (history skipped: time)"]\n    if log:\n        out.append("commits that added or removed it (newest first):")\n        out.extend("  " + short(c) for c in log)\n        for c in log[:HUNK_TRIES]:\n            hunks = newest_hunks(ws, c.split()[0], name, start)\n            if hunks:\n                out.append(f"what {c.split()[0]} changed around it:")\n                out.extend(hunks)\n                break\n    else:\n        out.append("commits that added or removed it: none found")\n    notes = git(ws, ["grep", "-n", "-I", "-i", "-F", "-e", name, "--"] + LOG_PATHS, start) or []\n    if notes:\n        out.append("changelog:")\n        out.extend("  " + short(n) for n in notes[:LOG_LINES])\n    return out\n\n\ndef main():\n    start = time.time()\n    names = names_from_args()\n    if not names:\n        print("NO NAMES: pass 2 to 5 exact names from the issue as positional_args, for example "\n              "[\\"function_name\\", \\"ClassName\\", \\"option_name\\"].")\n        return\n    ws = workspace()\n    done = os.path.join(ws, DONE_FILE)\n    if ONCE and os.path.exists(done):  # also after the harness re-runs the stage with no history: show the result again\n        print("ALREADY DONE: the search already ran and a second call is refused. Its result was:\\n"\n              + open(done, errors="replace").read() + "\\n" + REPLY)\n        return\n    parts = [f"REPOSITORY EVIDENCE for {\', \'.join(names)} (read-only searches; the issue stays the specification)"]\n    for n in names:\n        parts.extend(section(ws, n, start))\n    text = "\\n".join(parts)\n    if len(text) > OUT_MAX:\n        text = text[:OUT_MAX] + "\\n[cut]"\n    if ONCE:\n        os.makedirs(os.path.dirname(done), exist_ok=True)\n        open(done, "w").write(text)\n        text += "\\nThis was the only search: a second call is refused. " + REPLY\n    print(text + f"\\n[done in {time.time() - start:.0f} s]")\n\n\nif __name__ == "__main__":\n    main()\n'}}
